h,w=24,27
a=[[6]*w for _ in range(h)]
frames=[(0,3,0,3,0),(2,6,9,13,8),(0,4,20,24,9),(5,9,1,5,3),(8,14,9,15,5),(10,17,17,24,9),(12,17,1,6,5),(16,21,10,15,3)]
for r0,r1,c0,c1,b in frames:
 for r in range(r0,r1+1):
  for c in range(c0,c1+1):
   if r in (r0,r1) or c in (c0,c1): a[r][c]=b
# Interior fill is 7 if the enclosed dimensions are odd, otherwise 2.
for r0,r1,c0,c1,b in frames:
 fill=7 if (r1-r0-1)%2 else 2
 for r in range(r0+1,r1):
  for c in range(c0+1,c1): a[r][c]=fill
